package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g13khgny9ajkx8h02k0ayyh7752je74qy89lrj8p"), 60),
		},
		"Add validator g13khgny9ajkx8h02k0ayyh7752je74qy89lrj8p",
		"Add operator g13khgny9ajkx8h02k0ayyh7752je74qy89lrj8p to the active valset with voting power 60.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

package main

import (
	"time"
	"encoding/hex"

	"gno.land/p/aib/ibc/lightclient/tendermint"
	"gno.land/p/aib/ibc/types"
	"gno.land/p/aib/ics23"
	"gno.land/r/aib/ibc/core"
)
func hexDec(s string) []byte {
  b, err := hex.DecodeString(s)
                 if err != nil { panic(err) }
  return b
}
func main(cur realm) {
	// CreateClient
	var (
		chainID      = "atomone-testnet-1"
		latestHeight = types.Height{ 
			RevisionNumber: 1,
			RevisionHeight: 8758549,
		}
		clientState = tendermint.ClientState{
			ChainID:         chainID,
			TrustLevel:      tendermint.Fraction{2, 3},
			UnbondingPeriod: time.Second * 1814400,
			TrustingPeriod:  time.Second * 1209600,
			MaxClockDrift:   time.Second * 20,
			LatestHeight:    latestHeight,
			ProofSpecs:      ics23.GetSDKProofSpecs(),
		}
		apphash        = hexDec("068dd5ad4449e154aa8e3bc2a827952fb6efacd4bd7a73330afcca5f1a1be7a9")
		valhash        = hexDec("2515002b11a8354d94d2ee666e396300d0bd8817321cef0e897c674ba1c7635e")
		timestamp      = time.Unix(1788258780, 304850060)
		consensusState = tendermint.ConsensusState{
			Timestamp:          timestamp,
			Root:               tendermint.MerkleRoot{Hash: apphash[:]},
			NextValidatorsHash: valhash[:],
		}
	)
	id := core.CreateClient(cross(cur), clientState, consensusState)
	println(id)
}

